$('#import-file').addEventListener('change',async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Backup is too large.');const b=JSON.parse(await f.text());if(b.schema_version!==1||!b.overrides||!b.notes||!b.links)throw Error('Choose a Valencia browser-backup JSON file.');for(const [id,s] of Object.entries(b.overrides)){if(!plan.sessions.some(x=>x.id===id))throw Error('Backup has an unknown session.');M.validateSession(s);}if(b.settings&&(!['Europe/London','Europe/Madrid','Asia/Seoul'].includes(b.settings.timezone)||!M.finite(b.settings.maxHR)||b.settings.maxHR<140||b.settings.maxHR>230))throw Error('Invalid settings in backup.');settings={...settings,...b.settings};overrides=b.overrides;links=b.links;notes=b.notes;persist();render();toast('Backup imported.');}catch(err){toast(err.message);}finally{e.target.value='';}});
$('#detail').addEventListener('cancel',()=>{selected=null;editor=null;modalToken++;});
window.addEventListener('hashchange',()=>{state.tab=location.hash.slice(1);render();});
try{await loadData();render();setInterval(async()=>{if(document.hidden)return;const stamp=dataInfo.updated;await loadData(true);if(dataInfo.updated!==stamp&&!$('#detail').open)render();},60000);}catch(err){$('#app').innerHTML=`<div class="boot">V / 26<span>Could not load the dashboard.</span><p style="font:14px/1.8 Arial;margin-top:20px">Open this through your GitHub Pages URL, or run <code>python3 -m http.server 8000 --directory docs</code> from the project folder.<br>${esc(err.message)}</p><button onclick="location.reload()">Retry</button></div>`;console.error(err);}
